  }, "\uADF8\uAC00 \uC6F9\uC5D0\uC11C \uC2DC\uAC04\uC744 \uBCF4\uB0B4\uBA74\uC11C \uCD5C\uACE0\uC758 \uC0C1\uD488\uC744 \uD3B8\uB9AC\uD558\uAC8C \uC548\uB0B4\uD558\uB294 \uAC00\uC774\uB4DC\uB85C \uACC4\uC18D \uB418\uB3CC\uC544\uAC00\uB294 \uACBD\uD5D8\uC744 \uD588\uB2E4. \uC774 \uAC00\uC774\uB4DC\uB294 \uC57C\uD6C4 Yahoo\uB77C\uACE0 \uBD88\uB838\uB2E4.")), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uC2A4\uD0E0\uD37C\uB4DC\uB300\uD559\uAD50\uC5D0 \uB2E4\uB2C8\uB294 19\uC138\uC758 \uCE68\uCC29\uD55C \uD559\uC0DD\uC774 \uB098\uC774\uC5D0 \uBE44\uD574 \uD6E8\uC52C \uB354 \uC9C0\uD61C\uB86D\uAC8C \uBCF4\uC600\uB2E4. \uADF8\uAC00 \uBC14\uB85C \uC0D8 \uC62C\uD2B8\uBA3C Sam Altman\uC774\uC5C8\uB294\uB370, \uB098\uC911\uC5D0 \uADF8\uB808\uC774\uC5C4\uC758 \uB4A4\uB97C \uC774\uC5B4 \uC640\uC774\uCF64\uBE44\uB124\uC774\uD130\uC758 \uAE30\uC5C5\uC815\uC2E0\uC744 \uACC4\uC2B9\uD588\uB2E4.")), mdx("p", null, "\uC2A4\uD0C0\uD2B8\uC5C5 \uC52C\uC5D0\uC11C \uC0B4\uBA70 \uB0B4\uAC00 \uC790\uC8FC \uC811\uD588\uB358 \uBB38\uD654 \uD639\uC740 \uCF54\uB4DC\uB4E4\uC758 \uAE30\uC6D0\uC744 \uC54C \uC218 \uC788\uC5C8\uB2E4. \uB354 \uB9CE\uC740 \uC131\uC7A5\uC744 \uC704\uD574 \uC801\uC790\uB97C \uAC10\uC218\uD558\uBA70 \uB354 \uB9CE\uC740 \uC790\uAE08\uC73C\uB85C \uB9C8\uCF00\uD305\uACFC \uB9E4\uCD9C \uC131\uC7A5\uC5D0 \uB3C8\uC744 \uB4E4\uC774\uBD93\uB294, \uC18C\uC704 \"\uB3C8\uC744 \uD0DC\uC6B4\uB2E4\"\uD558\uB294 \uC2DD\uC758 \uC131\uC7A5\uC740 \uC190 \uB9C8\uC0AC\uC694\uC2DC\uC640 \uADF8\uAC00 \uD22C\uC790\uD55C \uC57C\uD6C4\uC5D0\uC11C \uC2DC\uC791\uB410\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uC57C\uD6C4\uAC00 \uC131\uC7A5\uD558\uAE30 \uC704\uD55C \uC5F4\uC1E0\uB294 \uC57C\uD6C4\uAC00 \uACC4\uC18D \uC131\uC7A5\uD574\uC57C \uD55C\uB2E4\uB294 \uAC83\uC774\uC5C8\uB2E4. \uB530\uB77C\uC11C \uC57C\uD6C4\uAC00 \uCD08\uAE30\uC5D0 \uC218\uC785\uC744 \uBC1C\uC0DD\uC2DC\uD0A4\uB294 \uB370 \uC131\uACF5\uD558\uB354\uB77C\uB3C4 \uC774\uAC83\uC774 \uC218\uC775\uC73C\uB85C \uC774\uC5B4\uC9C0\uC9C0\uB294 \uC54A\uC558\uB2E4. \uAD11\uACE0 \uC218\uC785\uC744 \uB9C8\uCF00\uD305 \uC9C0\uCD9C\uB85C \uC7AC\uD22C\uC790\uD574\uC57C\uB9CC \uC0AC\uC5C5\uC744 \uACC4\uC18D \uD655\uC7A5\uD560 \uC218 \uC788\uC5C8\uB2E4.")), mdx("p", null, "\uC54C\uD1A0\uC2A4\uBCA4\uCC98\uC2A4\uC640 \uAC19\uC740 VC\uC758 \uD22C\uC790\uBC95\uC774\uB77C\uACE0 \uC54C\uB824\uC84C\uB358, \uD68C\uC0AC\uAC00 \uC5B4\uB290\uC815\uB3C4 \uC131\uC7A5\uD55C \uD6C4\uC5D0\uB3C4 \uC804\uBB38 \uACBD\uC601\uC778\uC744 \uC120\uC784\uD558\uC9C0 \uC54A\uACE0 \uCC3D\uC5C5\uC790\uB97C \uBBFF\uC73C\uBA70 \uD68C\uC0AC\uC758 \uB2E4\uC74C \uB2E8\uACC4\uB85C \uC804\uC9C4\uC2DC\uD0A4\uB294 \uAC83\uC740 \uD53C\uD130 \uD2F8\uACFC \uAC19\uC740 \uC5D4\uC824 \uD22C\uC790\uC790\uB4E4\uC758 \uD0DC\uB3C4\uC5D0\uC11C \uC654\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uC5D4\uC824\uD22C\uC790\uC790\uB85C\uC11C \uB354\uD398\uC774\uC2A4\uBD81\uC744 \uC9C0\uC6D0\uD558\uBA74\uC11C \uC774\uC0AC\uD68C \uC774\uC0AC\uB85C\uB3C4 \uD65C\uB3D9\uD55C \uD53C\uD130 \uD2F8\uC740 \uCC3D\uC5C5\uC790\uAC00 \uBCA4\uCC98\uD22C\uC790\uC790\uC640 \uC9C0\uBC30\uAD8C\uC744 \uACF5\uC720\uD558\uC9C0 \uB9D0\uACE0 \uC790\uC2E0\uC758 \uD68C\uC0AC\uC5D0 \uB300\uD55C \uACBD\uC601\uAD8C\uC744 \uC720\uC9C0\uD574\uC57C \uD55C\uB2E4\uACE0 \uAC15\uC870\uD588\uB2E4")), mdx("p", null, "\uC720\uB2C8\uCF58 \uAE30\uC5C5\uC758 \uB4F1\uC7A5\uC774 \uC790\uC5F0\uC2A4\uB7EC\uC6B4 \uD22C\uC790 \uC5ED\uC0AC \uD750\uB984\uC758 \uC0B0\uBB3C\uC774\uB77C\uB294 \uAC83\uC774 \uD765\uBBF8\uB86D\uB2E4. 50\uB144\uC774 \uB118\uB294 \uC2DC\uAC04\uB3D9\uC548 \uBCA4\uCC98\uCE90\uD53C\uD0C8\uC740 \uD68C\uC0AC\uB97C \uD1B5\uC81C\uD558\uB824\uB294 \uC2DC\uB3C4\uB97C \uACC4\uC18D\uD574\uC11C \uC904\uC5EC\uC654\uB2E4. \uC2E4\uB9AC\uCF58\uBC38\uB9AC\uC5D0\uC11C\uB294 90\uB144\uB300\uBD80\uD130 \uC804\uBB38\uACBD\uC601\uC778\uC744 \uC120\uC784\uD558\uC9C0 \uC54A\uACE0 \uCC3D\uC5C5\uC790\uB97C \uBBFF\uACE0 \uB2E4\uC74C \uC2A4\uD14C\uC774\uC9C0\uB85C \uC774\uD589\uD558\uB294 \uC2E4\uD5D8\uC774 \uC2DC\uC791\uB418\uC5C8\uB2E4."), mdx("p", null, "\uB9C8\uD06C \uC800\uCEE4\uBC84\uADF8\uB294 \uCC98\uC74C\uBD80\uD130 \uC5D4\uC824\uD22C\uC790\uB97C \uB9CE\uC774 \uBC1B\uC558\uACE0, \uC5D4\uC824\uD22C\uC790\uC790\uB4E4\uC740 \uCC3D\uC5C5\uC790\uC5D0\uAC8C \uB9CE\uC740 \uC9C0\uBD84\uC744 \uC694\uAD6C\uD558\uC9C0 \uC54A\uC558\uB2E4. \uC720\uB9AC \uBC00\uB108\uC640 \uAC19\uC740 \uC131\uC7A5 \uD22C\uC790\uC790\uB4E4\uC740 2009\uB144 \uD55C\uBC1C \uB2A6\uAC8C \uD398\uC774\uC2A4\uBD81\uC5D0 \uD22C\uC790\uD558\uBA74\uC11C \uACFC\uAC70 \uD22C\uC790\uC790\uB4E4\uC744 \uC5D1\uC2EF\uC2DC\uCF1C\uC8FC\uAE30\uB3C4 \uD588\uC9C0\uB9CC \uC774\uC0AC\uD68C \uC790\uB9AC\uB3C4 \uC694\uAD6C\uD558\uC9C0 \uC54A\uC558\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uAE30\uC220\uAE30\uC5C5 \uCC3D\uC5C5\uC790\uB4E4\uC740 \uBC00\uB108\uC5D0\uAC8C \uC790\uAE08\uC744 \uC9C0\uC6D0\uBC1B\uC74C\uC73C\uB85C\uC368, \uB300\uCCB4\uB85C \uC774\uC0AC\uD68C \uC774\uC0AC \uC790\uB9AC\uB97C \uC694\uAD6C\uD588\uB358 \uC804\uD1B5\uC801\uC778 \uC0AC\uC801 \uD22C\uC790\uC790\uB4E4\uC758 \uAC10\uC2DC\uC5D0\uC11C \uBC97\uC5B4\uB0A0 \uC218 \uC788\uC5C8\uB2E4. \uC774\uC640 \uD568\uAED8 \uADF8\uB4E4\uC740 \uC6D4\uC2A4\uD2B8\uB9AC\uD2B8 \uC560\uB110\uB9AC\uC2A4\uD2B8\uB4E4\uC758 \uBD84\uAE30\uBCC4 \uC790\uB8CC \uC694\uAD6C, \uADDC\uC81C\uC5D0 \uADFC\uAC70\uD55C \uC815\uBCF4\uACF5\uAC1C \uC694\uAD6C, \uC790\uC0AC \uC8FC\uC2DD\uACFC\uB294 \uBC18\uB300\uBC29\uD5A5\uC73C\uB85C \uD22C\uC790\uD558\uB824\uB294 \uD5E4\uC9C0\uD380\uB4DC \uD2B8\uB808\uC774\uB354\uB4E4\uC758 \uD589\uC704\uCC98\uB7FC \uC8FC\uC2DD\uACF5\uBAA8\uC5D0 \uB530\uB978 \uADDC\uC728\uC744 \uD53C\uD574 \uAC08 \uC218 \uC788\uC5C8\uB2E4.")), mdx("p", null, "\uCC3D\uC5C5\uC790\uB294 \uD22C\uC790\uAE08\uC744 \uBB34\uCC99 \uBC1B\uC544 \uD68C\uC0AC\uC758 \uAE30\uC5C5\uAC00\uCE58\uB97C \uBD88\uB838\uC9C0\uB9CC IPO\uB97C \uBBF8\uB8E8\uBA70 \uC5D1\uC2EF \uC555\uBC15\uC5D0\uC11C \uBC97\uC5B4\uB0AC\uB2E4. \uC774\uB7EC\uD55C \uBC1C\uC804 \uACFC\uC815\uC774 \uAE30\uC5C5\uAC00\uCE58\uAC00 \uB9E4\uC6B0 \uB192\uC74C\uC5D0\uB3C4 \uC0C1\uC7A5\uC744 \uD558\uC9C0 \"\uC54A\uC544\uB3C4 \uB418\uB294\", \uC720\uB2C8\uCF58 \uAE30\uC5C5\uC744 \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uBC1C\uBA85\uD574\uB0C8\uB2E4."), mdx("p", null, "\uC0AC\uB78C\uB4E4\uC740 \uC88B\uC740 \uD22C\uC790 \uAE30\uD68C\uAC00 \uC654\uC744 \uB54C \uBB34\uC870\uAC74 \uB3C8\uC744 \uB123\uACA0\uB2E4\uACE0 \uD558\uACA0\uC9C0\uB9CC, \uB9CE\uC740 \uC6B0\uB7C9 \uD68C\uC0AC\uB294 \uD22C\uC790\uD560 \uAE30\uD68C \uC790\uCCB4\uAC00 \uD76C\uC18C\uD558\uB2E4. \uC0C1\uC7A5\uD68C\uC0AC\uAC00 \uC544\uB2CC OpenAI\uB098 SpaceX\uC5D0 \uB3C8\uC744 \uB123\uAE30\uAC00 \uD798\uB4E0 \uAC83\uCC98\uB7FC. \uC5B4\uB5A4 \uD22C\uC790\uB294 \uBD84\uC11D\uD558\uACE0 \uC804\uB7B5\uC744 \uC870\uC815\uD558\uAE30 \uBCF4\uB2E4, \uAE30\uD68C\uAC00 \uC654\uC744 \uB54C \uBC14\uB85C \uB0B4 \uC790\uC6D0\uC744 \uBC00\uC5B4\uB123\uB294 \uBC29\uC2DD\uC73C\uB85C \uC9C4\uD589\uD574\uC57C \uD55C\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uC2A4\uCF67\uC740 \uC774 \uBC29\uBB38\uAC1D\uC5D0\uAC8C \uC6D0\uD55C\uB2E4\uBA74 \uB85C\uBE44\uC5D0 \uC549\uC544 \uC788\uC744 \uC218\uB294 \uC788\uC9C0\uB9CC, \uC8FC\uC2DD\uC744 \uC5BB\uC744 \uAC00\uB2A5\uC131\uC740 \uC81C\uB85C\uB77C\uACE0 \uB300\uB2F5\uD588\uB2E4. / \uBAAC\uD130\uADDC\uB294 \uAE30\uB2E4\uB9AC\uACA0\uB2E4\uACE0 \uB300\uB2F5\uD588\uB2E4. \uADF8\uB7EC\uACE0\uB294 \uB2E4\uB978 \uC0AC\uB78C\uC758 \uC0AC\uBB34\uC2E4\uC5D0\uC11C \uC7A0\uC744 \uC790\uBA74\uC11C \uAC71\uC815\uD574\uC57C \uD558\uB294 \uC720\uC77C\uD55C \uBB38\uC81C\uB294 \uCE58\uC544 \uC704\uC0DD\uC774\uB77C\uB294 \uB4EF\uC774 \uC774\uB807\uAC8C \uB9D0\uD588\uB2E4. \u201C\uC800 \uCE6B\uC194\uB3C4 \uC788\uC5B4\uC694. \uC5EC\uAE30 \uADF8\uB0E5 \uB4DC\uB7EC\uB204\uC6CC \uC788\uACA0\uC2B5\uB2C8\uB2E4.\u201D / \uADF8\uB0A0 \uC800\uB141 7\uC2DC 15\uBD84 \uC804\uC5D0 \uC2A4\uCF67\uC774 \uB2E4\uC2DC \uB098\uD0C0\uB098\uC11C \uB9D0\uD588\uB2E4. \u201C\uBAAC\uD130\uADDC \uC528, \uB2F9\uC2E0\uC740 \uC815\uB9D0 \uC6B4\uC774 \uC88B\uC740 \uC0AC\uB78C\uC785\uB2C8\uB2E4.\u201D \uC6CC\uC988\uB2C8\uC545\uC774 \uC9D1\uC744 \uC0AC\uAE30\uB85C \uD588\uB294\uB370, \uD604\uAE08\uC744 \uB9C8\uB828\uD558\uAE30 \uC704\uD574 \uC790\uAE30 \uC8FC\uC2DD\uC758 \uC77C\uBD80\uB97C \uD314\uACA0\uB2E4\uB294 \uAC83\uC774\uB2E4.")), mdx("p", null, "\uC190 \uB9C8\uC0AC\uC694\uC2DC\uB294 \uC678\uACC4\uC778\uC774\uB098 \uCE68\uB7B5\uC790\uB85C \uD45C\uD604\uB41C\uB2E4. \uB2F9\uC2DC \uC2E4\uB9AC\uCF58\uBC38\uB9AC\uC758 \uC0AC\uB78C\uB4E4\uC774 \uB2F9\uD669\uC2A4\uB7EC\uC6B8\uB9CC\uC740 \uD55C\uAC8C, \uC6B0\uB9AC\uB098\uB77C\uB85C \uCE58\uBA74 \uC0BC\uC131\uC774\uB098 \uD604\uB300 \uC815\uB3C4 \uB418\uB294 \uAE30\uC5C5\uC758 \uCD1D\uC218\uAC00(\uC774\uC7AC\uC6A9 \uAC19\uC740 \uC0AC\uB78C\uC774) \uD55C\uAD6D\uC5D0\uC11C \uBC88 \uB3C8 \uC2F8\uB4E4\uACE0 \uC2E4\uB9AC\uCF58\uBC38\uB9AC\uB85C \uC640\uC11C \uCD08\uC704\uD5D8 \uAE30\uC220\uC8FC \uD22C\uC790\uB97C \uAC08\uAE30\uACE0 \uC788\uC5C8\uB2E4."), mdx("blockquote", null, mdx("p", {
