  }, "\uC57C\uD6C4 \uD300\uC774 \uACB0\uB860\uC744 \uB0B4\uB9AC\uAE30 \uC804\uC5D0 \uC190\uC815\uC758\uB294 \uB450 \uBC88\uC9F8\uB85C \uD30C\uACA9\uC801\uC778 \uC218\uB97C \uB450\uC5C8\uB2E4. \uADF8\uB294 \uBAA8\uB9AC\uCE20\uC640 \uCC3D\uC5C5\uC790\uB4E4\uC5D0\uAC8C \uC57C\uD6C4\uC758 \uC8FC\uC694 \uACBD\uC7C1\uC790\uB4E4\uC774 \uB204\uAD6C\uC778\uC9C0 \uBB3C\uC5C8\uB2E4. / \uADF8\uB4E4\uC740 \uC774\uB807\uAC8C \uB300\uB2F5\uD588\uB2E4. \u201C\uC775\uC0AC\uC774\uD2B8\uC640 \uB77C\uC774\uCF54\uC2A4\uC785\uB2C8\uB2E4.\u201D / \uC190\uC815\uC758\uB294 \uBE44\uC11C \uC911 \uD55C \uC0AC\uB78C\uC5D0\uAC8C \uC774\uB807\uAC8C \uC9C0\uC2DC\uD588\uB2E4. \u201C\uBC1B\uC544 \uC801\uAC8C.\u201D / \uADF8\uB7EC\uACE0\uB294 \uBAA8\uB9AC\uCE20\uC640 \uCC3D\uC5C5\uC790\uB4E4\uC5D0\uAC8C \uC774\uB807\uAC8C \uB9D0\uD588\uB2E4. \u201C\uB0B4\uAC00 \uC57C\uD6C4\uC5D0 \uD22C\uC790\uD558\uC9C0 \uC54A\uC73C\uBA74 \uC775\uC0AC\uC774\uD2B8\uC640 \uB77C\uC774\uCF54\uC2A4\uC5D0 \uD22C\uC790\uD574\uC11C \uC57C\uD6C4\uB97C \uB9DD\uD558\uAC8C \uD560 \uAC83\uC785\uB2C8\uB2E4.\u201D")), mdx("p", null, "\uD3F4 \uADF8\uB808\uC774\uC5C4\uC758 2000\uB144\uB300 \uCD08\uBC18 \uBC1C\uC5B8\uC740 IT\uAE30\uC5C5\uC774 \uADF8 \uC0DD\uBA85\uC744 \uC9C0\uC18D\uD558\uB294\uB370 \uC788\uC5B4 \uD544\uC694\uD55C \uC544\uC8FC \uB2E8\uC21C\uD55C \uC9C4\uC2E4\uC744 \uC77C\uAE68\uC6B4\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uC0AC\uC6A9\uC790\uB4E4\uC774 \uC88B\uC544\uD558\uB294 \uAC83\uC744 \uB9CC\uB4E4\uACE0, \uB2F9\uC2E0\uC774 \uBC84\uB294 \uAC83\uBCF4\uB2E4 \uC801\uAC8C \uC9C0\uCD9C\uD558\uB77C. \uADF8\uAC8C \uADF8\uB807\uAC8C \uC5B4\uB824\uC6B4\uAC00?")), mdx("p", null, "\uB2E8\uC21C\uD788 \uD5C8\uB9AC\uB760\uB97C \uC878\uB77C\uB9E4\uB77C\uB294 \uC774\uC57C\uAE30\uB294 \uC544\uB2C8\uACE0, \uADF8\uB294 \uBCA4\uCC98\uCE90\uD53C\uD0C8\uC744(\uB354 \uAC70\uCE60\uAC8C\uB294 \"\uC678\uBD80\uC5D0\uC11C \uB4E4\uC5B4\uC624\uB294 \uC790\uBCF8\uACFC \uC774\uD574\uAD00\uACC4\uC790\"\uB97C) \uCC29\uCDE8\uC790\uB85C \uC815\uC758\uD558\uACE0 \uCC3D\uC5C5\uC790\uB4E4\uACFC \uAC1C\uBC1C\uC790\uB4E4\uC774 \uC790\uC2E0\uC744 \uC704\uD574 \uC77C\uD558\uAE38 \uBC14\uB7AC\uB2E4. \uD22C\uC790 \uC2DC\uC7A5\uC774 \uC794\uB729 \uCABC\uADF8\uB77C\uB4E0 \uC9C0\uAE08 \uD55C\uAD6D \uC2A4\uD0C0\uD2B8\uC5C5\uB4E4\uC5D0\uB3C4 \uC2DC\uC0AC\uC810\uC774 \uC788\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4."), mdx("p", null, "\uB610 \uD558\uB098 \uC5B8\uAE09\uD560\uB9CC\uD55C \uAC83, \uC800\uC790\uC758 \uBCA4\uCC98\uCE90\uD53C\uD0C8\uC5D0 \uB300\uD55C \uD0DC\uB3C4\uAC00 \uB2E4\uBD84\uD788 \uAE0D\uC815\uC801\uC774\uB2E4."), mdx("blockquote", null, mdx("p", {
